// reject definitely-absent ids before touching cache/DB
async function getProduct(id) {
  if (!validIds.mightContain(id)) {
    return null;                 // definitely absent -> fast 404
  }
  const cached = await cache.get(id);
  if (cached) return cached;

  const row = await db.getProduct(id);   // possibly present -> check DB
  await cache.set(id, row);
  return row;
}

// when a new product is created
async function createProduct(p) {
  await db.insertProduct(p);
  // (filter is rebuilt nightly from the DB)
}
